  ipf_frame m1 sp j16 jt p bsz bb vl nm ->
  ipf_pure sp P IN E lo c p0 bs -> p0 <= q <= p0 + Z.of_nat (length bs) ->
  p0 <= p -> q <= p -> p + 2 <= p0 + Z.of_nat (length bs) ->
  evt rsegs (ipf_segA_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo c pad7 pad2 p0 bs q p m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -4288)) gp tp t0 t1 t2 (wz E) (wz IN)
              (wz p) a1 a2 a3 a4 a5 a6 a7
              (wz (p0 + Z.of_nat (length bs))) (wz P) (wz G_FIELD_TABLE_GUARD) (wz G_FIELD_TABLE) s6x s7x
              (Z_to_bv 64 (bv_unsigned sp + -128)) (wz 13) (wz 10) (wz 1) t3 t4 t5 t6)
        F (Z_to_bv 64 IPF_HEAD) fc None m1 (seg_rom rsegs)).

